class Transaction:
    """事务上下文：正常提交，异常回滚。"""

    def __init__(self, conn):
        self.conn = conn

    def __enter__(self):
        self.conn.execute("BEGIN")
        return self.conn

    def __exit__(self, exc_type, exc_value, traceback):
        if exc_type is None:
            self.conn.execute("COMMIT")
            print("事务已提交")
        else:
            self.conn.execute("ROLLBACK")
            print(f"发生 {exc_type.__name__}，事务已回滚")
        return False  # 异常继续传播，让上层知道失败


