import functools
import time

def retry(times=3, delay=1.0, exceptions=(Exception,)):
    """带参数的重试装饰器"""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_error = None
            for attempt in range(1, times + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    last_error = e
                    print(f"  第 {attempt} 次调用失败：{e}")
                    if attempt < times:
                        time.sleep(delay)
            raise last_error  # 全部失败，抛出最后一次异常
        return wrapper
    return decorator

