import functools

class CallCounter:
    """统计函数被调用了多少次"""

    def __init__(self, func):
        functools.update_wrapper(self, func)  # 类装饰器用这个代替 @wraps
        self.func = func
        self.count = 0

    def __call__(self, *args, **kwargs):
        self.count += 1
        print(f"{self.func.__name__} 第 {self.count} 次被调用")
        return self.func(*args, **kwargs)

    def reset(self):
        self.count = 0

