import functools
import logging
import time

logging.basicConfig(level=logging.INFO, format="%(levelname)s | %(message)s")
logger = logging.getLogger(__name__)

def log_call(level=logging.INFO, log_args=True, log_result=False):
    """记录函数调用的装饰器"""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            name = f"{func.__module__}.{func.__qualname__}"
            if log_args:
                logger.log(level, f"调用 {name} args={args} kwargs={kwargs}")
            start = time.perf_counter()
            try:
                result = func(*args, **kwargs)
            except Exception as e:
                cost = (time.perf_counter() - start) * 1000
                logger.exception(f"{name} 异常 [{cost:.1f}ms]：{e}")
                raise  # 记录后原样抛出，不要吞掉
            cost = (time.perf_counter() - start) * 1000
            if log_result:
                logger.log(level, f"{name} 返回 {result!r} [{cost:.1f}ms]")
            else:
                logger.log(level, f"{name} 完成 [{cost:.1f}ms]")
            return result
        return wrapper
    return decorator

@log_call(log_result=True)
def calc_discount(amount, vip_level):
    rates = {0: 1.0, 1: 0.95, 2: 0.9, 3: 0.85}
    return round(amount * rates.get(vip_level, 1.0), 2)

